mapper.select:
WITH RECURSIVE ancestors AS ( SELECT parent_id, child_id, 1 AS depth FROM riff_schedule_job_chain WHERE child_id = #{childId}
UNION ALL
SELECT jc.parent_id, jc.child_id, a.depth + 1 FROM riff_schedule_job_chain jc INNER JOIN ancestors a ON jc.child_id = a.parent_id WHERE a.depth < 20 AND jc.parent_id > 0 ) SELECT parent_id FROM ancestors
